package com.profa.payment;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/payments")public class PaymentController{final PaymentRepository r;public PaymentController(PaymentRepository r){this.r=r;}@PostMapping public Payment initiate(Authentication a,@RequestBody Payment x){x.setPayerId(UUID.fromString(a.getName()));x.setStatus("PENDING");return r.save(x);}@PostMapping("/webhook/{provider}")public Map<String,String> webhook(@PathVariable String provider,@RequestBody Map<String,Object> payload){return Map.of("status","accepted","provider",provider);}}